"use client";
import { useEffect } from "react";

/**
 * InvertFill — buttons invert from the pointer: this tracks where the pointer enters and leaves any
 * element matching `selector` and writes it to --x / --y on it; the button's CSS grows a circle of
 * the inverse colour from there (ui/button/button.css .btn::after). One delegated listener for the
 * whole page, so buttons rendered later (the configurator's) get it too. Without it the circle grows
 * from the centre.
 */
export function InvertFill({ selector = ".btn" }: { selector?: string }) {
  useEffect(() => {
    const mark = (e: PointerEvent) => {
      const el = (e.target as Element | null)?.closest?.<HTMLElement>(selector);
      if (!el || (e.relatedTarget instanceof Node && el.contains(e.relatedTarget))) return; // a move inside it
      const r = el.getBoundingClientRect();
      el.style.setProperty("--x", `${(e.clientX - r.left).toFixed(1)}px`);
      el.style.setProperty("--y", `${(e.clientY - r.top).toFixed(1)}px`);
    };
    document.addEventListener("pointerover", mark, { passive: true });
    document.addEventListener("pointerout", mark, { passive: true });
    return () => {
      document.removeEventListener("pointerover", mark);
      document.removeEventListener("pointerout", mark);
    };
  }, [selector]);
  return null;
}

/*
 * Buttons. Each variant and each context sets only colour variables; the shape and the effect are
 * shared. The effect (fx/invert-fill): on hover the button inverts — a circle of --btn-fill grows
 * from the point where the pointer came in (--x / --y), the text takes --btn-fill-ink, a hairline
 * ring in that colour keeps the edge; leaving, the circle shrinks back toward the exit point.
 * The label's letters roll (RollText) and the arrow leaves up-right as its copy comes in.
 */
.btn {
  --h: 52px;
  --btn-bg: transparent;
  --btn-ink: var(--ink);
  --btn-line: transparent;
  --btn-fill: var(--ink);
  --btn-fill-ink: var(--on-ink);
  --btn-fill-line: transparent;
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 1.75rem;
  height: var(--h);
  padding: 0 1.35rem 0 1.85rem;
  border: 0;
  border-radius: 999px;
  font: 500 1rem/1 var(--font-sans);
  letter-spacing: -0.005em;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  isolation: isolate;
  overflow: hidden;
  color: var(--btn-ink);
  background: var(--btn-bg);
  box-shadow: inset 0 0 0 1px var(--btn-line);
  transition:
    color 0.45s var(--ease-out),
    box-shadow 0.45s var(--ease-out),
    transform 0.25s var(--ease-out);
  -webkit-tap-highlight-color: transparent;
}
/* the fill: a circle from the pointer's entry point, wide enough to cover the button from any corner */
.btn::after {
  content: "";
  position: absolute;
  left: var(--x, 50%);
  top: var(--y, 50%);
  z-index: -1;
  width: 260%;
  aspect-ratio: 1;
  border-radius: 50%;
  background: var(--btn-fill);
  transform: translate(-50%, -50%) scale(0);
  transition: transform 0.7s var(--ease-out);
  pointer-events: none;
}
.btn:hover,
.btn:focus-visible { color: var(--btn-fill-ink); box-shadow: inset 0 0 0 1px var(--btn-fill-line); }
.btn:hover::after,
.btn:focus-visible::after { transform: translate(-50%, -50%) scale(1); }
.btn:active { transform: scale(0.97); }
.btn__label { position: relative; display: inline-block; }

.btn__icon {
  position: relative;
  flex: none;
  width: 18px;
  height: 18px;
  overflow: hidden;
}
.arrow {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: transform var(--dur) var(--ease-out);
}
.arrow--b { transform: translate(-120%, 120%); }
.btn:hover .arrow--a,
.btn:focus-visible .arrow--a { transform: translate(120%, -120%); }
.btn:hover .arrow--b,
.btn:focus-visible .arrow--b { transform: translate(0, 0); }

/* variants: colours only */
.btn--ghost {
  --btn-line: rgb(246 246 243 / 0.6);
  --btn-fill: var(--ink);
  --btn-fill-ink: var(--on-ink);
  --btn-fill-line: var(--ink);
}
.btn--line {
  --h: 50px;
  height: var(--h);
  gap: 1.2rem;
  padding: 0 1.2rem 0 1.5rem;
  --btn-line: rgb(246 246 243 / 0.32);
  --btn-fill: var(--ink);
  --btn-fill-ink: var(--on-ink);
  --btn-fill-line: var(--ink);
}
/* primary: solid; inverts to the page's black with its own colour as text and ring */
.btn--primary {
  --h: clamp(56px, calc(var(--vh, 1vh) * 6.2), 64px);
  --btn-bg: var(--ink);
  --btn-ink: var(--on-ink);
  --btn-fill: var(--bg);
  --btn-fill-ink: var(--ink);
  --btn-fill-line: var(--ink);
  gap: clamp(1.75rem, 3vw, 2.75rem);
  padding: 0 1.6rem 0 clamp(1.75rem, 2.8vw, 2.6rem);
  font-size: clamp(1rem, 0.35vw + 0.9rem, 1.125rem);
}
@media (max-width: 420px) {
  .btn--primary { width: 100%; justify-content: space-between; }
}

.btn--xs { --h: 40px; height: 40px; gap: 1rem; padding: 0 0.9rem 0 1.1rem; font-size: var(--fs-small); }
.btn--sm { --h: 50px; height: 50px; gap: 1.2rem; padding: 0 1.2rem 0 1.5rem; font-size: var(--fs-body); }

/* contexts (specificity above the variants, so the order of the stylesheets doesn't matter):
   the first screen in lime; the page, the topbar and the footer in ember */
.hero .btn--primary { --btn-bg: var(--signal); --btn-ink: var(--on-ink); --btn-fill-ink: var(--signal); --btn-fill-line: var(--signal); }
.hero .btn--ghost { --btn-fill: var(--signal); --btn-fill-line: var(--signal); }
:is(.page, .topbar, .footer) .btn--primary { --btn-bg: var(--ember); --btn-ink: var(--on-ink); --btn-fill-ink: var(--ember-ink); --btn-fill-line: var(--ember); }
:is(.page, .topbar, .footer) :is(.btn--ghost, .btn--line) { --btn-fill: var(--ember); --btn-fill-ink: var(--on-ink); --btn-fill-line: var(--ember); }

@media (prefers-reduced-motion: reduce) {
  .btn::after { transition-duration: 1ms; }
}

.link {
  color: var(--ink);
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-decoration-color: rgb(210 86 28 / 0.75);
  text-underline-offset: 3px;
  transition: text-decoration-color var(--dur-fast);
}
.link:hover { color: var(--ember-ink); text-decoration-color: var(--ember); }
